import json,sys,unittest
suite=unittest.TestSuite(unittest.defaultTestLoader.discover('tests/godot',pattern=p) for p in ('test_profile_probe_evidence.py','test_profile_readback.py'))
def flatten(s):
 for t in s:
  if isinstance(t,unittest.TestSuite):yield from flatten(t)
  else:yield t.id()
ids=list(flatten(suite))
r=unittest.TextTestRunner(verbosity=2).run(suite)
print('GT03_UNIT_REPAIR_COMPLETE '+json.dumps({'run':r.testsRun,'failures':len(r.failures),'errors':len(r.errors),'skips':len(r.skipped),'tests':ids}),flush=True)
sys.exit(not r.wasSuccessful())
